{"command":"ls -la lab/; echo "---"; python3 - <<'PY'
import json,glob,os
for f in sorted(glob.glob('lab/*.json')):
    try:
        r=json.load(open(f))
    except Exception as e:
        print(f,'ERR',e); continue
    if 'value' in r:
        print(f, 'mode=',r.get('mode'), 'x=',r.get('x'),'y=',r.get('y'),'value=',r.get('value'),'imp=',r.get('impurity'),'spent=',r.get('spent'))
    elif 'offset' in r:
        print(f,'CAL offset=',r.get('offset'),'instrument=',r.get('instrument'),'spent=',r.get('spent'))
    elif 'selected_model' in r:
        print(f,'MODEL',r.get('selected_model'),'rec=',bool(r.get('recommendation')),'best=',r.get('best_measured'))
    elif 'observations' in r:
        print(f,'INPUT n=',len(r['observations']),'remaining=',r.get('remaining_budget'))
    else:
        print(f,'OTHER keys=',list(r)[:10])
